SET local check_function_bodies = off;

-- Whether the caller may read the subject a row of deadlines names, apart from
-- the permission of the types in the gate (ADR 1232): the subject row has to be
-- visible to them (its own policies apply), with the record grants and team
-- check of the types that have them. plpgsql, so a statement plans only the
-- branch of the type it reads and a table a later module creates binds late.
create or replace function "better_supabase"."deadline_subject_row_readable"(subject_type text, subject_id text, tenant uuid)
returns boolean
language plpgsql
stable
security invoker
cost 1000
set search_path = ''
as $$
begin
  case deadline_subject_row_readable.subject_type
    when 'message' then return coalesce(exists (select 1 from "better_supabase"."messages" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'conversation' then return coalesce(exists (select 1 from "better_supabase"."conversations" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'channel' then return coalesce(exists (select 1 from "better_supabase"."channels" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'company' then return coalesce(exists (select 1 from "better_supabase"."companies" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'person' then return coalesce(exists (select 1 from "better_supabase"."people" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'deal' then return coalesce(exists (select 1 from "better_supabase"."deals" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'course' then return coalesce(exists (select 1 from "better_supabase"."courses" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'post' then return coalesce(exists (select 1 from "better_supabase"."posts" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'activity' then return coalesce(exists (select 1 from "better_supabase"."activities" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'quote' then return coalesce(exists (select 1 from "better_supabase"."quotes" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'work_item' then return coalesce(exists (select 1 from "better_supabase"."work_items" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'employee' then return coalesce(exists (select 1 from "better_supabase"."employees" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'ledger_account' then return coalesce(exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'invoice' then return coalesce(exists (select 1 from "better_supabase"."invoices" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'product' then return coalesce(exists (select 1 from "better_supabase"."products" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'product_variant' then return coalesce(exists (select 1 from "better_supabase"."product_variants" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'rfq' then return coalesce(exists (select 1 from "better_supabase"."rfqs" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'till' then return coalesce(exists (select 1 from "better_supabase"."tills" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'order' then return coalesce(exists (select 1 from "better_supabase"."orders" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'calendar_event' then return coalesce(exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'booking' then return coalesce(exists (select 1 from "better_supabase"."bookings" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'asset' then return coalesce(exists (select 1 from "better_supabase"."assets" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'asset_location' then return coalesce(exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'lease' then return coalesce(exists (select 1 from "better_supabase"."leases" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'expense_report' then return coalesce(exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'expense_line' then return coalesce(exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'donation_fund' then return coalesce(exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'warranty_claim' then return coalesce(exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'work_order' then return coalesce(exists (select 1 from "better_supabase"."work_orders" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'shipment' then return coalesce(exists (select 1 from "better_supabase"."shipments" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'contract' then return coalesce(exists (select 1 from "better_supabase"."contracts" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'control' then return coalesce(exists (select 1 from "better_supabase"."controls" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'compliance_policy' then return coalesce(exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'qualification_type' then return coalesce(exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'risk' then return coalesce(exists (select 1 from "better_supabase"."risks" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'case' then return coalesce(exists (select 1 from "better_supabase"."cases" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'inspection' then return coalesce(exists (select 1 from "better_supabase"."inspections" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'inspection_program' then return coalesce(exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'inspection_finding' then return coalesce(exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'form' then return coalesce(exists (select 1 from "better_supabase"."forms" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'meeting' then return coalesce(exists (select 1 from "better_supabase"."meetings" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'meeting_decision' then return coalesce(exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'maintenance_plan' then return coalesce(exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'dam_usage_right' then return coalesce(exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'lims_sample' then return coalesce(exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'tax_code' then return coalesce(exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'production_order' then return coalesce(exists (select 1 from "better_supabase"."production_orders" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'work_center' then return coalesce(exists (select 1 from "better_supabase"."work_centers" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'bank_account' then return coalesce(exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'care_plan' then return coalesce(exists (select 1 from "better_supabase"."care_plans" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'incident' then return coalesce(exists (select 1 from "better_supabase"."incidents" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'content_entry' then return coalesce(exists (select 1 from "better_supabase"."content_entries" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'document' then return coalesce(exists (select 1 from "better_supabase"."documents" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'customer' then return coalesce(exists (select 1 from "public"."customers" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."organization_id" = deadline_subject_row_readable.tenant) and deadline_subject_row_readable.tenant in (select better_supabase.tenant_ids_with('customers.read')), false);
    when 'drive_node' then return coalesce(exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant and (deadline_subject_row_readable.tenant in (select better_supabase.tenant_ids_with('drive.read')) and coalesce("better_supabase"."drive_node_readable"(s."id"), false))), false);
    when 'organization' then return coalesce(exists (select 1 from "public"."organizations" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."id" = deadline_subject_row_readable.tenant), false);
    when 'application' then return coalesce(exists (select 1 from "better_supabase"."applications" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."tenant_id" = deadline_subject_row_readable.tenant), false);
    when 'change_request' then return coalesce(exists (select 1 from "public"."change_requests" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."organization_id" = deadline_subject_row_readable.tenant), false);
    when 'project' then return coalesce(exists (select 1 from "public"."projects" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."organization_id" = deadline_subject_row_readable.tenant), false);
    when 'task' then return coalesce(exists (select 1 from "public"."tasks" s where s."id" = (deadline_subject_row_readable.subject_id)::uuid and s."organization_id" = deadline_subject_row_readable.tenant), false);
    else return coalesce("better_supabase"."deadline_subject_readable"(deadline_subject_row_readable.subject_type, deadline_subject_row_readable.subject_id, deadline_subject_row_readable.tenant), false);
  end case;
end;
$$;
revoke execute on function "better_supabase"."deadline_subject_row_readable"(text, text, uuid) from public, anon;
grant execute on function "better_supabase"."deadline_subject_row_readable"(text, text, uuid) to authenticated, service_role;

DROP POLICY "bsb_deadlines_read" ON "better_supabase"."deadlines";

DROP POLICY "bsb_tenant_scope_select" ON "better_supabase"."deadlines";

create policy bsb_deadlines_read on "better_supabase"."deadlines"
  for select to authenticated
  using ("tenant_id" in (select better_supabase.tenant_ids_with('deadlines.read')) and case "better_supabase"."deadlines"."subject_type"
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = ("better_supabase"."deadlines"."subject_id")::uuid and s."organization_id" = "better_supabase"."deadlines"."tenant_id") and "better_supabase"."deadlines"."tenant_id" in (select better_supabase.tenant_ids_with('customers.read'))
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = ("better_supabase"."deadlines"."subject_id")::uuid and s."tenant_id" = "better_supabase"."deadlines"."tenant_id" and ("better_supabase"."deadlines"."tenant_id" in (select better_supabase.tenant_ids_with('drive.read')) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = ("better_supabase"."deadlines"."subject_id")::uuid and s."id" = "better_supabase"."deadlines"."tenant_id")
    when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = ("better_supabase"."deadlines"."subject_id")::uuid and s."organization_id" = "better_supabase"."deadlines"."tenant_id")
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = ("better_supabase"."deadlines"."subject_id")::uuid and s."organization_id" = "better_supabase"."deadlines"."tenant_id")
    when 'task' then exists (select 1 from "public"."tasks" s where s."id" = ("better_supabase"."deadlines"."subject_id")::uuid and s."organization_id" = "better_supabase"."deadlines"."tenant_id")
    else (coalesce("better_supabase"."deadlines"."subject_type" = any(array['message', 'conversation', 'channel', 'company', 'person', 'deal', 'course', 'post', 'activity', 'quote', 'work_item', 'employee', 'ledger_account', 'invoice', 'product', 'product_variant', 'rfq', 'till', 'order', 'calendar_event', 'booking', 'asset', 'asset_location', 'lease', 'expense_report', 'expense_line', 'donation_fund', 'warranty_claim', 'work_order', 'shipment', 'contract', 'control', 'compliance_policy', 'qualification_type', 'risk', 'case', 'inspection', 'inspection_program', 'inspection_finding', 'form', 'meeting', 'meeting_decision', 'maintenance_plan', 'dam_usage_right', 'lims_sample', 'tax_code', 'production_order', 'work_center', 'bank_account', 'care_plan', 'incident', 'content_entry', 'document', 'application']), false) = false or ("better_supabase"."deadlines"."tenant_id", "better_supabase"."deadlines"."subject_type") in (select t.tenant, g.type from better_supabase.tenant_ids_with('messages.read') as t(tenant) cross join unnest(array['message', 'conversation', 'channel']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('contacts.read') as t(tenant) cross join unnest(array['company', 'person']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('deals.read') as t(tenant) cross join unnest(array['deal']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('courses.read') as t(tenant) cross join unnest(array['course']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('posts.read') as t(tenant) cross join unnest(array['post']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('activities.read') as t(tenant) cross join unnest(array['activity']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('quotes.read') as t(tenant) cross join unnest(array['quote']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('tasks.read') as t(tenant) cross join unnest(array['work_item']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('employees.read') as t(tenant) cross join unnest(array['employee']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('ledger.read') as t(tenant) cross join unnest(array['ledger_account']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('invoices.read') as t(tenant) cross join unnest(array['invoice']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('catalog.read') as t(tenant) cross join unnest(array['product', 'product_variant']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('rfqs.read') as t(tenant) cross join unnest(array['rfq']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('tills.read') as t(tenant) cross join unnest(array['till']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('orders.read') as t(tenant) cross join unnest(array['order']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('calendar.read') as t(tenant) cross join unnest(array['calendar_event']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('bookings.read') as t(tenant) cross join unnest(array['booking']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('assets.read') as t(tenant) cross join unnest(array['asset', 'asset_location']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('leases.read') as t(tenant) cross join unnest(array['lease']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('expenses.read') as t(tenant) cross join unnest(array['expense_report', 'expense_line']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('donations.read') as t(tenant) cross join unnest(array['donation_fund']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('warranty.read') as t(tenant) cross join unnest(array['warranty_claim']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('dispatch.read') as t(tenant) cross join unnest(array['work_order']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('shipments.read') as t(tenant) cross join unnest(array['shipment']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('contracts.read') as t(tenant) cross join unnest(array['contract']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('compliance.read') as t(tenant) cross join unnest(array['control', 'compliance_policy']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('qualifications.read') as t(tenant) cross join unnest(array['qualification_type']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('risks.read') as t(tenant) cross join unnest(array['risk']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('cases.read') as t(tenant) cross join unnest(array['case']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('inspections.read') as t(tenant) cross join unnest(array['inspection', 'inspection_program', 'inspection_finding']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('forms.read') as t(tenant) cross join unnest(array['form']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('meetings.read') as t(tenant) cross join unnest(array['meeting', 'meeting_decision']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('maintenance.read') as t(tenant) cross join unnest(array['maintenance_plan']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('dam.read') as t(tenant) cross join unnest(array['dam_usage_right']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('lims.read') as t(tenant) cross join unnest(array['lims_sample']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('tax.read') as t(tenant) cross join unnest(array['tax_code']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('manufacturing.read') as t(tenant) cross join unnest(array['production_order', 'work_center']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('banking.read') as t(tenant) cross join unnest(array['bank_account']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('care_plans.read') as t(tenant) cross join unnest(array['care_plan']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('incidents.read') as t(tenant) cross join unnest(array['incident']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('content.read') as t(tenant) cross join unnest(array['content_entry']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('documents.read') as t(tenant) cross join unnest(array['document']) as g(type) union all select t.tenant, g.type from better_supabase.tenant_ids_with('hiring.read') as t(tenant) cross join unnest(array['application']) as g(type))) and "better_supabase"."deadline_subject_row_readable"("better_supabase"."deadlines"."subject_type", "better_supabase"."deadlines"."subject_id", "better_supabase"."deadlines"."tenant_id")
  end);

create policy bsb_tenant_scope_select on "better_supabase"."deadlines" as restrictive
  for select to public
  using (
    "tenant_id" in (select better_supabase.member_organization_ids())
